CREATE TABLE IF NOT EXISTS "AGENDAMENTO_PORTAL" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "tipo" VARCHAR(100),
  "data_hora" TIMESTAMP,
  "assunto" VARCHAR(1000),
  "nome" VARCHAR(500),
  "nome_solicitante" VARCHAR(500),
  "telefone" VARCHAR(50),
  "cpf_cnpj" VARCHAR(50),
  "responsavel" VARCHAR(250),
  "observacoes" VARCHAR(2000),
  "status" VARCHAR(50) DEFAULT 'Pendente' NOT NULL,
  "criado_por" VARCHAR(250),
  "dt_criacao" TIMESTAMP DEFAULT (now() AT TIME ZONE 'America/Sao_Paulo') NOT NULL,
  "concluido_por" VARCHAR(250),
  "dt_cheg" TIMESTAMP,
  "enviou" BOOLEAN DEFAULT FALSE NOT NULL,
  PRIMARY KEY ("id")
);

CREATE INDEX IF NOT EXISTS "AGENDAMENTO_PORTAL_IX_AGENDAMENTO_PORTAL_DATA_HORA" ON "AGENDAMENTO_PORTAL" ("data_hora");

CREATE INDEX IF NOT EXISTS "AGENDAMENTO_PORTAL_IX_AGENDAMENTO_PORTAL_STATUS" ON "AGENDAMENTO_PORTAL" ("status");

CREATE TABLE IF NOT EXISTS "CARGAS_PORTARIA" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "filial" VARCHAR(50),
  "carga" VARCHAR(200),
  "dt_entrega" TIMESTAMP,
  "placa" VARCHAR(50),
  "tipo_entrega" VARCHAR(100),
  "motorista" VARCHAR(250),
  "peso" NUMERIC(12,2),
  "status" VARCHAR(50),
  "telefone" VARCHAR(50),
  "cpf_cnpj" VARCHAR(50),
  "criado_por" VARCHAR(250),
  "dt_criacao" TIMESTAMP DEFAULT (now() AT TIME ZONE 'America/Sao_Paulo') NOT NULL,
  PRIMARY KEY ("id")
);

CREATE INDEX IF NOT EXISTS "CARGAS_PORTARIA_IX_CARGAS_PORTARIA_DT_ENTREGA" ON "CARGAS_PORTARIA" ("dt_entrega");

CREATE TABLE IF NOT EXISTS "HORARIOS_AGENDAMENTO" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "pedido" VARCHAR(100),
  "data" TIMESTAMP,
  "criado_por" VARCHAR(200),
  "nome_cli" VARCHAR(500),
  "cod_cli" VARCHAR(100),
  "categoria" VARCHAR(50),
  "observacao" VARCHAR(1000),
  "status" VARCHAR(50) DEFAULT 'PENDENTE' NOT NULL,
  "data_entrada" TIMESTAMP,
  "data_saida" TIMESTAMP,
  "dt_criacao" TIMESTAMP DEFAULT (now() AT TIME ZONE 'America/Sao_Paulo') NOT NULL,
  PRIMARY KEY ("id")
);

CREATE INDEX IF NOT EXISTS "HORARIOS_AGENDAMENTO_IX_HORARIOS_AGENDAMENTO_PEDIDO" ON "HORARIOS_AGENDAMENTO" ("pedido");

CREATE UNIQUE INDEX IF NOT EXISTS "HORARIOS_AGENDAMENTO_IX_HORARIOS_AGENDAMENTO_UNQ_DATA" ON "HORARIOS_AGENDAMENTO" ("data") WHERE "data" IS NOT NULL;

CREATE TABLE IF NOT EXISTS "VISITANTES" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nome" VARCHAR(500),
  "dt_inclusao" TIMESTAMP DEFAULT (now() AT TIME ZONE 'America/Sao_Paulo') NOT NULL,
  "agendamento_id" INTEGER,
  "telefone" VARCHAR(50),
  "cpf_cnpj" VARCHAR(50),
  PRIMARY KEY ("id")
);

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'FK_VISITANTES_AGENDAMENTO') THEN
    ALTER TABLE "VISITANTES" ADD CONSTRAINT "FK_VISITANTES_AGENDAMENTO" FOREIGN KEY ("agendamento_id") REFERENCES "AGENDAMENTO_PORTAL" ("id") ON DELETE SET NULL;
  END IF;
END $$;
